def mst(pts):
    import itertools
    n=len(pts); edges=[]
    for i,j in itertools.combinations(range(n),2):
        d=abs(pts[i][0]-pts[j][0])+abs(pts[i][1]-pts[j][1])
        edges.append((d,i,j))
    edges.sort(); parent=list(range(n))
    def find(x):
        while parent[x]!=x: parent[x]=parent[parent[x]]; x=parent[x]
        return x
    chosen=[]
    for d,i,j in edges:
        ri,rj=find(i),find(j)
        if ri!=rj: parent[ri]=rj; chosen.append((pts[i],pts[j]))
    return chosen

def transform(g):
    g=[row[:] for row in g]
    P=centers(g)
    for a,b in mst(P): seg(g,a,b)
    return g

